"""
    Remaps input_val from source domain to target domain.
    No clamping is performed, the result can be outside of the target domain
    if the input is outside of the source domain.
    """
def remap_unbound(
    input_val: Any, in_from: Any, in_to: Any, out_from: Any, out_to: Any
) -> object {
    out_range = out_to - out_from;
    in_range = in_to - in_from;
    in_val = input_val - in_from;
    val = (float(in_val) / in_range) * out_range;
    out_val = out_from + val;
    return out_val;
}

"""
    truncate a given number to the chosen decimal place
    """
def truncate(number: Any, decimals: Any = 0) -> object {
    multiplier = 10 ** decimals;
    return (int((number * multiplier)) / multiplier);
}

"""
    creates a single string with all authors with only first letter of the firstname followed by a dot and surname.
    Author names are sperated by comma except for the last author which is seperated via 'and'.
    """
def authors_to_string(names: Any) -> object {
    string_authors = '';
    d = ', ';
    for (idx, name) in enumerate(names) {
        (first, von, last, jr) = name;
        if first {
            first = first[0] + '.';
        }
        if (idx == (len(names) - 2)) {
            d = ' and ';
        }
        if (idx == (len(names) - 1)) {
            d = '';
        }
        string_authors += (
            ' '.join(
                part
                for part in [first, von, last, jr]
                if part
            )
            + d
        );
    }
    return string_authors;
}

