def pick(seq: Any, func: Any, maxobj: Any = None) -> object {
    maxscore = None;
    for `obj in seq {
        score = func(`obj);
        if ((maxscore is None) or (maxscore < score)) {
            (maxscore, maxobj) = (score, `obj);
